CREATE TABLE IF NOT EXISTS "pay_app" (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "app_key"              varchar(64)   NOT NULL,
    "name"              varchar(64)   NOT NULL,
    "status"            tinyint       NOT NULL,
    "remark"            varchar(255)           DEFAULT NULL,
    `order_notify_url`    varchar(1024) NOT NULL,
    `refund_notify_url` varchar(1024) NOT NULL,
    "creator"           varchar(64)            DEFAULT '',
    "create_time"       datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar(64)            DEFAULT '',
    "update_time"       datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit(1)        NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT = '支付应用';

CREATE TABLE IF NOT EXISTS "pay_channel" (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code"        varchar(32)    NOT NULL,
    "status"      tinyint(4)     NOT NULL,
    "remark"      varchar(255)            DEFAULT NULL,
    "fee_rate"    double         NOT NULL DEFAULT 0,
    "app_id"      bigint(20)     NOT NULL,
    "config"      varchar(10240) NOT NULL,
    "creator"     varchar(64)    NULL     DEFAULT '',
    "create_time" datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)    NULL     DEFAULT '',
    "update_time" datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit(1)         NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default  '0',
    PRIMARY KEY ("id")
) COMMENT = '支付渠道';

CREATE TABLE IF NOT EXISTS `pay_order` (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    `app_id`               bigint(20)    NOT NULL,
    `channel_id`           bigint(20)             DEFAULT NULL,
    `channel_code`         varchar(32)            DEFAULT NULL,
    `merchant_order_id`    varchar(64)   NOT NULL,
    `subject`              varchar(32)   NOT NULL,
    `body`                 varchar(128)  NOT NULL,
    `notify_url`           varchar(1024) NOT NULL,
    `price`                bigint(20)    NOT NULL,
    `channel_fee_rate`     double                 DEFAULT 0,
    `channel_fee_price`    bigint(20)             DEFAULT 0,
    `status`               tinyint(4)    NOT NULL,
    `user_ip`              varchar(50)   NOT NULL,
    `user_id`              bigint(20)             DEFAULT NULL,
    `user_type`            tinyint(4)             DEFAULT NULL,
    `expire_time`          timestamp   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `success_time`         datetime(0)            DEFAULT CURRENT_TIMESTAMP,
    `notify_time`          datetime(0)            DEFAULT CURRENT_TIMESTAMP,
    `extension_id` bigint(20)             DEFAULT NULL,
    `no`                   varchar(64)   NULL,
    `refund_price`         bigint(20)    NOT NULL,
    `divide_plan_data`     varchar(4096) NULL,
    `channel_user_id`      varchar(255)           DEFAULT NULL,
    `channel_order_no`     varchar(64)            DEFAULT NULL,
    `creator`              varchar(64)            DEFAULT '',
    `create_time`          datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater`              varchar(64)            DEFAULT '',
    `update_time`          datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted`              bit(1)        NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT = '支付订单';

CREATE TABLE IF NOT EXISTS `pay_order_extension` (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    `no`           varchar(64)         NOT NULL,
    `order_id`           bigint(20)    NOT NULL,
    `channel_id`         bigint(20)    NOT NULL,
    `channel_code`       varchar(32)   NOT NULL,
    `user_ip`            varchar(50)   NULL     DEFAULT NULL,
    `status`             tinyint(4)    NOT NULL,
    `channel_extras`     varchar(1024) NULL     DEFAULT NULL,
    `channel_error_code`  varchar(64)  NULL,
    `channel_error_msg` varchar(64)    NULL,
    `channel_notify_data` varchar(1024)  NULL,
    `creator`            varchar(64)   NULL     DEFAULT '',
    `create_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater`            varchar(64)   NULL     DEFAULT '',
    `update_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted`            bit(1)        NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT = '支付订单拓展';

CREATE TABLE IF NOT EXISTS `pay_refund` (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    `no`           varchar(64)         NOT NULL,
    `app_id`             bigint(20)    NOT NULL,
    `channel_id`         bigint(20)    NOT NULL,
    `channel_code`       varchar(32)   NOT NULL,
    `order_id`           bigint(20)    NOT NULL,
    `order_no`           varchar(64)    NOT NULL,
    `merchant_order_id`  varchar(64)   NOT NULL,
    `merchant_refund_id` varchar(64)   NOT NULL,
    `notify_url`         varchar(1024) NOT NULL,
    `status`             tinyint(4)    NOT NULL,
    `pay_price`         bigint(20)    NOT NULL,
    `refund_price`      bigint(20)    NOT NULL,
    `reason`             varchar(256)  NOT NULL,
    `user_ip`            varchar(50)   NULL     DEFAULT NULL,
    `user_id`            bigint(20)    NULL     DEFAULT NULL,
    `user_type`          tinyint(4)    NULL     DEFAULT NULL,
    `channel_order_no`   varchar(64)   NOT NULL,
    `channel_refund_no`  varchar(64)   NULL     DEFAULT NULL,
    `success_time`       datetime(0)   NULL     DEFAULT NULL,
    `channel_error_code` varchar(128)  NULL     DEFAULT NULL,
    `channel_error_msg`  varchar(256)  NULL     DEFAULT NULL,
    `channel_notify_data` varchar(1024)  NULL,
    `fund_allocation_data` varchar(4096) NULL,
    `request_submitted_time` datetime(0) NULL,
    `creator`            varchar(64)   NULL     DEFAULT '',
    `create_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater`            varchar(64)   NULL     DEFAULT '',
    `update_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted`            bit(1)        NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT = '退款订单';

CREATE TABLE IF NOT EXISTS `pay_notify_task` (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    `app_id`             bigint(20)    NOT NULL,
    `type`               tinyint(4)    NOT NULL,
    `data_id`           bigint(20)    NOT NULL,
    `merchant_order_id`           varchar(64)    NOT NULL,
    `status`             tinyint(4)    NOT NULL,
    `next_notify_time`       datetime(0)   NULL     DEFAULT NULL,
    `last_execute_time`       datetime(0)   NULL     DEFAULT NULL,
    `notify_times`         int    NOT NULL,
    `max_notify_times`         int    NOT NULL,
    `notify_url`         varchar(1024) NOT NULL,
    `creator`            varchar(64)   NULL     DEFAULT '',
    `create_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater`            varchar(64)   NULL     DEFAULT '',
    `update_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted`            bit(1)        NOT NULL DEFAULT FALSE,
    `tenant_id`           bigint(20)    NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT = '支付通知任务';

CREATE TABLE IF NOT EXISTS `pay_notify_log` (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    `task_id`             bigint(20)    NOT NULL,
    `notify_times`         int    NOT NULL,
    `response`         varchar(1024) NOT NULL,
    `status`             tinyint(4)    NOT NULL,
    `creator`            varchar(64)   NULL     DEFAULT '',
    `create_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater`            varchar(64)   NULL     DEFAULT '',
    `update_time`        datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted`            bit(1)        NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT = '支付通知日志';

CREATE TABLE IF NOT EXISTS `pay_transfer` (
    "id" number NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    `no`                   varchar(64)   NOT NULL,
    `app_id`               bigint(20)    NOT NULL,
    `channel_id`           bigint(20)    NOT NULL,
    `channel_code`         varchar(32)   NOT NULL,
    `user_id`              bigint(20)    NULL     DEFAULT NULL,
    `user_type`            tinyint(4)    NULL     DEFAULT NULL,
    `merchant_transfer_id` varchar(64)   NOT NULL,
    `price`                bigint(20)    NOT NULL,
    `subject`              varchar(256)  NOT NULL,
    `user_account`         varchar(256)  NOT NULL,
    `user_name`            varchar(64)   NULL     DEFAULT NULL,
    `status`               tinyint(4)    NOT NULL,
    `notify_url`           varchar(1024) NULL     DEFAULT NULL,
    `user_ip`              varchar(50)   NULL     DEFAULT NULL,
    `channel_transfer_no`  varchar(64)   NULL     DEFAULT NULL,
    `success_time`         datetime(0)   NULL     DEFAULT NULL,
    `channel_error_code`   varchar(128)  NULL     DEFAULT NULL,
    `channel_error_msg`    varchar(256)  NULL     DEFAULT NULL,
    `channel_notify_data`  varchar(1024) NULL     DEFAULT NULL,
    `channel_extras`       varchar(1024) NULL     DEFAULT NULL,
    `channel_package_info` varchar(1024) NULL     DEFAULT NULL,
    `creator`              varchar(64)   NULL     DEFAULT '',
    `create_time`          datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater`              varchar(64)   NULL     DEFAULT '',
    `update_time`          datetime(0)   NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted`              bit(1)        NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT = '转账单';

CREATE TABLE IF NOT EXISTS `pay_fund_order` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `no` varchar(64) NOT NULL,
    `app_id` bigint NOT NULL,
    `channel_id` bigint DEFAULT NULL,
    `channel_code` varchar(32) DEFAULT NULL,
    `pay_order_id` bigint DEFAULT NULL,
    `pay_order_no` varchar(64) DEFAULT NULL,
    `merchant_order_id` varchar(64) DEFAULT NULL,
    `user_id` bigint DEFAULT NULL,
    `user_type` tinyint DEFAULT NULL,
    `trade_order_id` bigint DEFAULT NULL,
    `trade_order_sub_id` bigint DEFAULT NULL,
    `divide_plan_data` varchar(4096) DEFAULT NULL,
    `amount` bigint NOT NULL DEFAULT 0,
    `price` bigint NOT NULL DEFAULT 0,
    `fee_price` bigint NOT NULL DEFAULT 0,
    `divide_price` bigint NOT NULL DEFAULT 0,
    `refund_price` bigint NOT NULL DEFAULT 0,
    `clearing_status` tinyint NOT NULL DEFAULT 0,
    `divide_status` tinyint NOT NULL DEFAULT 0,
    `retry_count` int NOT NULL DEFAULT 0,
    `next_retry_time` datetime DEFAULT NULL,
    `last_error` varchar(512) DEFAULT NULL,
    `parent_merchant_no` varchar(64) DEFAULT NULL,
    `collection_merchant_no` varchar(64) DEFAULT NULL,
    `status` tinyint NOT NULL DEFAULT 0,
    `currency` varchar(8) NOT NULL DEFAULT 'CNY',
    `notify_url` varchar(1024) DEFAULT NULL,
    `success_time` datetime DEFAULT NULL,
    `channel_order_no` varchar(64) DEFAULT NULL,
    `channel_request_no` varchar(64) DEFAULT NULL,
    `channel_error_code` varchar(128) DEFAULT NULL,
    `channel_error_msg` varchar(256) DEFAULT NULL,
    `channel_notify_data` varchar(4096) DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_fund_order_no` (`no`),
    UNIQUE KEY `uk_pay_fund_order_pay_order` (`pay_order_id`),
    UNIQUE KEY `uk_pay_fund_order_merchant` (`app_id`, `merchant_order_id`),
    KEY `idx_pay_fund_order_pay_order` (`pay_order_id`),
    KEY `idx_pay_fund_order_status` (`status`, `id`)
);

CREATE TABLE IF NOT EXISTS `pay_fund_detail` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `no` varchar(64) NOT NULL,
    `fund_order_id` bigint NOT NULL,
    `fund_order_no` varchar(64) DEFAULT NULL,
    `pay_order_id` bigint DEFAULT NULL,
    `pay_order_no` varchar(64) DEFAULT NULL,
    `trade_order_id` bigint DEFAULT NULL,
    `trade_order_sub_id` bigint DEFAULT NULL,
    `trade_order_item_id` bigint DEFAULT NULL,
    `account_id` bigint DEFAULT NULL,
    `account_no` varchar(64) DEFAULT NULL,
    `merchant_id` bigint DEFAULT NULL,
    `merchant_no` varchar(64) DEFAULT NULL,
    `merchant_name` varchar(128) DEFAULT NULL,
    `divide_detail_no` varchar(64) DEFAULT NULL,
    `biz_type` tinyint DEFAULT NULL,
    `direction` tinyint DEFAULT NULL,
    `amount` bigint NOT NULL DEFAULT 0,
    `price` bigint NOT NULL DEFAULT 0,
    `fee_price` bigint NOT NULL DEFAULT 0,
    `divide_amount` bigint DEFAULT NULL,
    `refunded_amount` bigint NOT NULL DEFAULT 0,
    `returned_amount` bigint NOT NULL DEFAULT 0,
    `status` tinyint NOT NULL DEFAULT 0,
    `currency` varchar(8) NOT NULL DEFAULT 'CNY',
    `success_time` datetime DEFAULT NULL,
    `channel_detail_no` varchar(64) DEFAULT NULL,
    `channel_error_code` varchar(128) DEFAULT NULL,
    `channel_error_msg` varchar(256) DEFAULT NULL,
    `remark` varchar(255) DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_fund_detail_no` (`no`),
    UNIQUE KEY `uk_pay_fund_detail_order_sub_order` (`fund_order_id`, `trade_order_sub_id`),
    KEY `idx_pay_fund_detail_order` (`fund_order_id`),
    KEY `idx_pay_fund_detail_account` (`account_no`)
);

CREATE TABLE IF NOT EXISTS `pay_divide_request` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `no` varchar(64) NOT NULL,
    `request_no` varchar(64) DEFAULT NULL,
    `app_id` bigint NOT NULL,
    `channel_id` bigint DEFAULT NULL,
    `channel_code` varchar(32) DEFAULT NULL,
    `fund_order_id` bigint NOT NULL,
    `fund_order_no` varchar(64) DEFAULT NULL,
    `fund_detail_id` bigint DEFAULT NULL,
    `fund_detail_no` varchar(64) DEFAULT NULL,
    `trade_order_id` bigint DEFAULT NULL,
    `trade_order_sub_id` bigint DEFAULT NULL,
    `merchant_id` bigint DEFAULT NULL,
    `divide_detail_no` varchar(64) DEFAULT NULL,
    `merchant_order_id` varchar(64) DEFAULT NULL,
    `merchant_request_no` varchar(64) DEFAULT NULL,
    `amount` bigint NOT NULL DEFAULT 0,
    `price` bigint NOT NULL DEFAULT 0,
    `status` tinyint NOT NULL DEFAULT 0,
    `retry_count` int NOT NULL DEFAULT 0,
    `next_retry_time` datetime DEFAULT NULL,
    `channel_request_no` varchar(64) DEFAULT NULL,
    `request_data` varchar(4096) DEFAULT NULL,
    `response_data` varchar(4096) DEFAULT NULL,
    `channel_error_code` varchar(128) DEFAULT NULL,
    `channel_error_msg` varchar(256) DEFAULT NULL,
    `success_time` datetime DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_divide_request_no` (`no`),
    UNIQUE KEY `uk_pay_divide_request_request_no` (`request_no`),
    UNIQUE KEY `uk_pay_divide_request_detail` (`fund_detail_id`),
    UNIQUE KEY `uk_pay_divide_request_channel` (`channel_request_no`),
    UNIQUE KEY `uk_pay_divide_request_merchant` (`app_id`, `merchant_request_no`),
    UNIQUE KEY `uk_pay_divide_request_fund_order` (`fund_order_id`),
    KEY `idx_pay_divide_request_status` (`status`, `id`)
);

CREATE TABLE IF NOT EXISTS `pay_refund_fund_detail` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `no` varchar(64) NOT NULL,
    `refund_id` bigint DEFAULT NULL,
    `refund_no` varchar(64) DEFAULT NULL,
    `pay_order_id` bigint DEFAULT NULL,
    `pay_order_no` varchar(64) DEFAULT NULL,
    `fund_order_id` bigint NOT NULL,
    `fund_order_no` varchar(64) DEFAULT NULL,
    `fund_detail_id` bigint DEFAULT NULL,
    `fund_detail_no` varchar(64) DEFAULT NULL,
    `after_sale_id` bigint DEFAULT NULL,
    `merchant_id` bigint DEFAULT NULL,
    `divide_detail_no` varchar(64) DEFAULT NULL,
    `divide_back_request_id` varchar(128) DEFAULT NULL,
    `app_id` bigint NOT NULL,
    `channel_id` bigint DEFAULT NULL,
    `channel_code` varchar(32) DEFAULT NULL,
    `merchant_refund_id` varchar(64) DEFAULT NULL,
    `amount` bigint NOT NULL DEFAULT 0,
    `price` bigint NOT NULL DEFAULT 0,
    `refund_status` tinyint NOT NULL DEFAULT 0,
    `divide_back_status` tinyint NOT NULL DEFAULT 10,
    `divide_back_success_time` datetime DEFAULT NULL,
    `status` tinyint NOT NULL DEFAULT 0,
    `reason` varchar(255) DEFAULT NULL,
    `channel_refund_no` varchar(64) DEFAULT NULL,
    `channel_error_code` varchar(128) DEFAULT NULL,
    `channel_error_msg` varchar(256) DEFAULT NULL,
    `channel_notify_data` varchar(4096) DEFAULT NULL,
    `retry_count` int NOT NULL DEFAULT 0,
    `next_retry_time` datetime DEFAULT NULL,
    `last_error` varchar(512) DEFAULT NULL,
    `success_time` datetime DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_refund_fund_detail_no` (`no`),
    UNIQUE KEY `uk_pay_refund_fund_detail_refund_detail` (`refund_id`, `fund_detail_id`),
    UNIQUE KEY `uk_pay_refund_fund_detail_refund_after_sale` (`refund_id`, `after_sale_id`),
    KEY `idx_pay_refund_fund_detail_refund` (`refund_id`),
    KEY `idx_pay_refund_fund_detail_order` (`fund_order_id`)
);

CREATE TABLE IF NOT EXISTS `pay_yeepay_merchant_account` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `app_id` bigint NOT NULL,
    `merchant_id` bigint DEFAULT NULL,
    `merchant_no` varchar(64) DEFAULT NULL,
    `request_no` varchar(128) DEFAULT NULL,
    `application_no` varchar(128) DEFAULT NULL,
    `sign_url` varchar(1024) DEFAULT NULL,
    `auth_url` varchar(1024) DEFAULT NULL,
    `materials_ref` varchar(255) DEFAULT NULL,
    `materials_version` int DEFAULT NULL,
    `submission_token` varchar(64) DEFAULT NULL,
    `submission_expire_time` datetime DEFAULT NULL,
    `last_request_time` datetime DEFAULT NULL,
    `last_error` varchar(512) DEFAULT NULL,
    `merchant_name` varchar(128) DEFAULT NULL,
    `account_no` varchar(64) DEFAULT NULL,
    `account_name` varchar(128) DEFAULT NULL,
    `account_type` tinyint DEFAULT NULL,
    `onboarding_status` tinyint NOT NULL DEFAULT 0,
    `status` tinyint NOT NULL DEFAULT 0,
    `bank_name` varchar(128) DEFAULT NULL,
    `bank_account_no` varchar(128) DEFAULT NULL,
    `contact_name` varchar(64) DEFAULT NULL,
    `contact_phone` varchar(32) DEFAULT NULL,
    `channel_data` varchar(4096) DEFAULT NULL,
    `remark` varchar(255) DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_yeepay_account_merchant` (`app_id`, `merchant_id`, `deleted`),
    UNIQUE KEY `uk_pay_yeepay_account_merchant_no` (`app_id`, `merchant_no`, `deleted`),
    UNIQUE KEY `uk_pay_yeepay_account_request` (`app_id`, `request_no`),
    UNIQUE KEY `uk_pay_yeepay_account_application` (`app_id`, `application_no`),
    KEY `idx_pay_yeepay_account_no` (`account_no`)
);

CREATE TABLE IF NOT EXISTS `pay_yeepay_event` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `event_id` varchar(128) NOT NULL,
    `event_no` varchar(128) DEFAULT NULL,
    `event_type` varchar(64) NOT NULL,
    `merchant_no` varchar(64) DEFAULT NULL,
    `request_id` varchar(128) DEFAULT NULL,
    `fund_order_no` varchar(64) DEFAULT NULL,
    `payload` varchar(8192) DEFAULT NULL,
    `raw_data_ref` varchar(255) DEFAULT NULL,
    `encrypted_original` mediumtext DEFAULT NULL,
    `decrypted_summary` varchar(4096) DEFAULT NULL,
    `status` tinyint NOT NULL DEFAULT 0,
    `ack_status` tinyint NOT NULL DEFAULT 0,
    `retry_count` int NOT NULL DEFAULT 0,
    `last_error` varchar(512) DEFAULT NULL,
    `event_time` datetime DEFAULT NULL,
    `processed_time` datetime DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_yeepay_event_id` (`event_id`),
    KEY `idx_pay_yeepay_event_status` (`status`, `id`)
);

CREATE TABLE IF NOT EXISTS `pay_reconciliation_record` (
    `id` bigint AUTO_INCREMENT PRIMARY KEY,
    `batch_no` varchar(64) NOT NULL,
    `app_id` bigint NOT NULL,
    `merchant_no` varchar(64) DEFAULT NULL,
    `channel_code` varchar(32) DEFAULT NULL,
    `reconciliation_date` date NOT NULL,
    `total_count` int NOT NULL DEFAULT 0,
    `total_amount` bigint NOT NULL DEFAULT 0,
    `total_price` bigint NOT NULL DEFAULT 0,
    `matched_count` int NOT NULL DEFAULT 0,
    `matched_amount` bigint NOT NULL DEFAULT 0,
    `difference_amount` bigint NOT NULL DEFAULT 0,
    `status` tinyint NOT NULL DEFAULT 0,
    `file_url` varchar(1024) DEFAULT NULL,
    `raw_data` varchar(8192) DEFAULT NULL,
    `error_msg` varchar(512) DEFAULT NULL,
    `started_time` datetime DEFAULT NULL,
    `completed_time` datetime DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT FALSE,
    `tenant_id` bigint NOT NULL DEFAULT 0,
    UNIQUE KEY `uk_pay_reconciliation_batch_no` (`batch_no`),
    KEY `idx_pay_reconciliation_merchant_date` (`merchant_no`, `reconciliation_date`)
);

CREATE TABLE IF NOT EXISTS `pay_fund_operation` (
  `id` bigint AUTO_INCREMENT,
  `action` varchar(64) NOT NULL,
  `target_id` bigint NOT NULL,
  `operator_id` bigint NOT NULL,
  `reason` varchar(512) NOT NULL,
  `external_evidence` varchar(1024) NOT NULL,
  `previous_state` text DEFAULT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT FALSE,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_fund_operation_target` (`tenant_id`, `action`, `target_id`)
);